/* From Uiverse.io by Mohammad-Rahme-576  - Tags: tooltip */
/* Container Styles */
.__UIV_SCOPE__ .tooltip-container {
  position: relative;
  display: inline-block;
  font-family: "Arial", sans-serif;
  overflow: visible;
}

/* Button Styles */
.__UIV_SCOPE__ .button-content {
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #6e8efb, #a777e3);
  color: white;
  padding: 14px 28px;
  border-radius: 50px;
  cursor: pointer;
  transition:
    background 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
    transform 0.3s ease,
    box-shadow 0.4s ease;
  box-shadow: 0 8px 15px rgba(0, 0, 0, 0.1);
  position: relative;
  z-index: 10;
  overflow: hidden;
}

.__UIV_SCOPE__ .button-content::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    135deg,
    rgba(110, 142, 251, 0.4),
    rgba(167, 119, 227, 0.4)
  );
  filter: blur(15px);
  opacity: 0;
  transition: opacity 0.5s ease;
  z-index: -1;
}

.__UIV_SCOPE__ .button-content::after {
  content: "";
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.3) 0%,
    rgba(255, 255, 255, 0) 70%
  );
  transform: scale(0);
  transition: transform 0.6s ease-out;
  z-index: -1;
}

.__UIV_SCOPE__ .button-content:hover::before {
  opacity: 1;
}

.__UIV_SCOPE__ .button-content:hover::after {
  transform: scale(1);
}

.__UIV_SCOPE__ .button-content:hover {
  background: linear-gradient(135deg, #a777e3, #6e8efb);
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.2);
  transform: translateY(-4px) scale(1.03);
}

.__UIV_SCOPE__ .button-content:active {
  transform: translateY(-2px) scale(0.98);
  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.15);
}

.__UIV_SCOPE__ .text {
  font-size: 18px;
  font-weight: 600;
  margin-right: 12px;
  white-space: nowrap;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
  transition: letter-spacing 0.3s ease;
}

.__UIV_SCOPE__ .button-content:hover .text {
  letter-spacing: 1px;
}

.__UIV_SCOPE__ .share-icon {
  fill: white;
  transition:
    transform 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55),
    fill 0.3s ease;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.1));
}

.__UIV_SCOPE__ .button-content:hover .share-icon {
  transform: rotate(180deg) scale(1.1);
  fill: #ffffff;
}

/* Tooltip Styles */
.__UIV_SCOPE__ .tooltip-content {
  position: absolute;
  top: 102%;
  left: 50%;
  transform: translateX(-50%) scale(0.8);
  background: white;
  border-radius: 15px;
  padding: 22px;
  box-shadow: 0 15px 30px rgba(0, 0, 0, 0.2);
  opacity: 0;
  visibility: hidden;
  transition:
    opacity 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55),
    transform 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55),
    visibility 0.5s ease;
  z-index: 100;
  pointer-events: none;
  backdrop-filter: blur(10px);
  background: rgba(255, 255, 255, 0.9);
}

.__UIV_SCOPE__ .tooltip-container:hover .tooltip-content {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) scale(1);
  pointer-events: auto;
}

/* Social Icons Styles */
.__UIV_SCOPE__ .social-icons {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.__UIV_SCOPE__ .social-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #f0f0f0;
  transition:
    transform 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55),
    background 0.3s ease,
    box-shadow 0.4s ease;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  position: relative;
  overflow: hidden;
}

.__UIV_SCOPE__ .social-icon::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at center,
    rgba(255, 255, 255, 0.8) 0%,
    rgba(255, 255, 255, 0) 70%
  );
  opacity: 0;
  transition: opacity 0.3s ease;
}

.__UIV_SCOPE__ .social-icon:hover::before {
  opacity: 1;
}

.__UIV_SCOPE__ .social-icon svg {
  width: 24px;
  height: 24px;
  fill: #333;
  transition:
    transform 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55),
    fill 0.3s ease;
  z-index: 1;
}

.__UIV_SCOPE__ .social-icon:hover {
  transform: translateY(-5px) scale(1.1);
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.15);
}

.__UIV_SCOPE__ .social-icon:active {
  transform: translateY(-2px) scale(1.05);
  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.1);
}

.__UIV_SCOPE__ .social-icon:hover svg {
  transform: scale(1.2);
  fill: white;
}

.__UIV_SCOPE__ .social-icon.twitter:hover {
  background: linear-gradient(135deg, #1da1f2, #1a91da);
}

.__UIV_SCOPE__ .social-icon.facebook:hover {
  background: linear-gradient(135deg, #1877f2, #165ed0);
}

.__UIV_SCOPE__ .social-icon.linkedin:hover {
  background: linear-gradient(135deg, #0077b5, #005e94);
}

/* Animation for Pulse Effect */
@keyframes pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(110, 142, 251, 0.4);
  }
  70% {
    box-shadow: 0 0 0 20px rgba(110, 142, 251, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(110, 142, 251, 0);
  }
}

.__UIV_SCOPE__ .button-content {
  animation: pulse 3s infinite;
}

/* Hover Ripple Effect */
@keyframes ripple {
  0% {
    transform: scale(0);
    opacity: 1;
  }
  100% {
    transform: scale(4);
    opacity: 0;
  }
}

.__UIV_SCOPE__ .button-content::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(255, 255, 255, 0.3);
  border-radius: inherit;
  transform: scale(0);
  opacity: 0;
}

.__UIV_SCOPE__ .button-content:active::before {
  animation: ripple 0.6s linear;
}

/* Tooltip Arrow */
.__UIV_SCOPE__ .tooltip-content::before {
  content: "";
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  border-width: 0 10px 10px 10px;
  border-style: solid;
  border-color: transparent transparent rgba(255, 255, 255, 0.9) transparent;
  filter: drop-shadow(0 -3px 3px rgba(0, 0, 0, 0.1));
}

/* Accessibility */
.__UIV_SCOPE__ .button-content:focus {
  outline: none;
  box-shadow:
    0 0 0 3px rgba(110, 142, 251, 0.5),
    0 8px 15px rgba(0, 0, 0, 0.1);
}

.__UIV_SCOPE__ .button-content:focus:not(:focus-visible) {
  box-shadow: 0 8px 15px rgba(0, 0, 0, 0.1);
}

/* Responsive Design */
@media (max-width: 768px) {
  .__UIV_SCOPE__ .button-content {
    padding: 12px 24px;
    border-radius: 40px;
  }

  .__UIV_SCOPE__ .text {
    font-size: 16px;
  }

  .__UIV_SCOPE__ .tooltip-content {
    width: 240px;
    padding: 18px;
  }

  .__UIV_SCOPE__ .social-icon {
    width: 44px;
    height: 44px;
  }

  .__UIV_SCOPE__ .social-icon svg {
    width: 20px;
    height: 20px;
  }
}

@media (max-width: 480px) {
  .__UIV_SCOPE__ .button-content {
    padding: 10px 20px;
  }

  .__UIV_SCOPE__ .text {
    font-size: 14px;
  }

  .__UIV_SCOPE__ .tooltip-content {
    width: 200px;
    padding: 15px;
  }

  .__UIV_SCOPE__ .social-icon {
    width: 40px;
    height: 40px;
  }

  .__UIV_SCOPE__ .social-icon svg {
    width: 18px;
    height: 18px;
  }
}

/* Dark Mode Support */
@media (prefers-color-scheme: dark) {
  .__UIV_SCOPE__ .tooltip-content {
    background: rgba(30, 30, 30, 0.9);
    color: white;
  }

  .__UIV_SCOPE__ .tooltip-content::before {
    border-color: transparent transparent rgba(30, 30, 30, 0.9) transparent;
  }

  .__UIV_SCOPE__ .social-icon {
    background: #2a2a2a;
  }

  .__UIV_SCOPE__ .social-icon svg {
    fill: #e0e0e0;
  }
}

/* Print Styles */
@media print {
  .__UIV_SCOPE__ .tooltip-container {
    display: none;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  .__UIV_SCOPE__ .button-content,
  .__UIV_SCOPE__ .share-icon,
  .__UIV_SCOPE__ .social-icon,
  .__UIV_SCOPE__ .tooltip-content {
    transition: none;
  }

  .__UIV_SCOPE__ .button-content {
    animation: none;
  }
}

/* Custom Scrollbar for Tooltip Content */
.__UIV_SCOPE__ .tooltip-content::-webkit-scrollbar {
  width: 6px;
}

.__UIV_SCOPE__ .tooltip-content::-webkit-scrollbar-track {
  background: #f1f1f1;
  border-radius: 3px;
}

.__UIV_SCOPE__ .tooltip-content::-webkit-scrollbar-thumb {
  background: #888;
  border-radius: 3px;
}

.__UIV_SCOPE__ .tooltip-content::-webkit-scrollbar-thumb:hover {
  background: #555;
}
